#!/usr/bin/env python3
"""Read-only fresh sleeping-worker census; not a grant or native runtime proof."""
import argparse,json,os,pathlib,stat,subprocess,hashlib,datetime
os.umask(0o077);assert os.geteuid()==0;p=argparse.ArgumentParser();p.add_argument('--pins',type=pathlib.Path,required=True);p.add_argument('--output',type=pathlib.Path,required=True);a=p.parse_args();st=a.pins.lstat();assert stat.S_ISREG(st.st_mode)and st.st_uid==0 and stat.S_IMODE(st.st_mode)==0o600;pin=json.loads(a.pins.read_text());assert pin['root_reviewed']is True and pin['gate_expected']is True;cid=pin['gateway_id'];assert cid!='382b1763ae4bd0fa21a871839af4be0d9c0c8e37dc7d57c85a68172cfff6be06';d=json.loads(subprocess.check_output(['docker','inspect',cid]))[0];assert d['Id']==cid and d['State']['Running']and d['Image']==pin['image']and d['Config']['Labels']['tunnex.lab']=='tunnex-bgp-20261007'
def ex(*args):return subprocess.check_output(['docker','exec',cid,*args],text=True)
ns=ex('readlink','/proc/1/ns/net').strip();assert ns==pin['namespace']and ns!='net:[4026532807]';assert ex('sha256sum','/binaries/tunnex-node').split()[0]==pin['node_sha256'];assert ex('sha256sum','/state/cert.pem').split()[0]==pin['cert_sha256'];processes=ex('ps','-eo','pid,comm');names=[line.split()[-1]for line in processes.splitlines()[1:]];assert all(x not in names for x in ['tunnex-node','charon','bgpd','zebra']);assert subprocess.run(['docker','exec',cid,'test','-e','/run/enrolled-restoration-release'],stdout=subprocess.DEVNULL).returncode==1;gate=ex('cat','/state/ipsec/restoration-startup-gate');assert gate==pin['gate_content'];routes=json.loads(ex('ip','-j','-4','route','show','table','all'));assert not any(x.get('dst')=='10.85.0.0/16'for x in routes);xfrm_state=json.loads(ex('ip','-j','xfrm','state'));xfrm_policy=json.loads(ex('ip','-j','xfrm','policy'));assert xfrm_state==[]and xfrm_policy==[];nft=json.loads(ex('nft','-j','list','ruleset'));assert not any(x.get('table',{}).get('name')=='tunnex_ipsec'for x in nft['nftables']);proof={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'cid':cid,'namespace':ns,'image':d['Image'],'node_mounted_sha256':pin['node_sha256'],'certificate_sha256':pin['cert_sha256'],'started_at':d['State']['StartedAt'],'pid1_host_pid':d['State']['Pid'],'pid1_comm':names[0],'processes':processes,'release_absent':True,'startup_gate_sha256':hashlib.sha256(gate.encode()).hexdigest(),'xfrm_states':[],'xfrm_policies':[],'payload_route_absent':True,'routes':routes,'nft':nft,'product_guard_drop_counter_claimed':False,'worker_started':False};assert not a.output.exists()
with a.output.open('x')as f:json.dump(proof,f,indent=2);f.flush();os.fsync(f.fileno())
print(json.dumps({'output':str(a.output),'cid':cid,'namespace':ns,'sleeping_noauthority_census_pass':True}))
